414			ret = mei_hbm_dispatch(dev, mei_hdr);
415			if (ret) {
416				dev_dbg(dev->dev, "mei_hbm_dispatch failed ret = %d\n",
417						ret);
418				goto end;
419			}
420			goto reset_slots;
421		}
